/**
 * Pages exported from a tool's examples, which its tool page links to (etalii.adp spec 074, FR-039). Site-owned, like
 * screenshot-notes.json: the pages are files under public/, generated by the desktop host from the examples the standalone
 * host carries, and nothing in the sources says they exist. Keyed by the tool's origin.
 */
export interface ExampleExport {
	/** The example's name, as a link reads. */
	name: string;
	/** Address of the page, with the site's base. */
	href: string;
	/** One sentence on what the example is about. */
	about: string;
}

const flowPage = (file: string) => `/adp/docs/causal-loop-flow-pages/${file}.html`;

export const exampleExports: Readonly<Record<string, readonly ExampleExport[]>> = {
	'systems/causal-loop-diagram': [
		{
			name: 'Business philosophy',
			href: flowPage('business-philosophy'),
			about: 'Whether a Business Philosophy study is applicable at a university of applied sciences: eighteen variables and ten loops.',
		},
		{
			name: 'Life insurance',
			href: flowPage('life-insurance'),
			about: 'The growth or decline of a life insurance company, redrawn from a public-domain U.S. Department of Energy figure: thirty-four variables and thirty-eight loops.',
		},
		{
			name: 'Mental health',
			href: flowPage('mental-health'),
			about: 'Why mental health at work stays out of sight: thirty variables and eight loops, a wicked problem drawn as structure alone.',
		},
		{
			name: 'On-call',
			href: flowPage('on-call'),
			about: 'Why an on-call rotation gets worse on its own.',
		},
		{
			name: 'Reference',
			href: flowPage('reference'),
			about: 'Every construct the causal loop diagram understands, in one diagram.',
		},
	],
};
